import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var i=JSON.parse(`{"title":"Image Editor","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/image-editor.md","filePath":"reporting/image-editor.md","lastUpdated":1781102819000}`),a={name:`reporting/image-editor.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /reporting/image-editor.md for this page in Markdown format</div><h1 id="image-editor" tabindex="-1">Image Editor <a class="header-anchor" href="#image-editor" aria-label="Permalink to “Image Editor”">​</a></h1><p>The built-in image editor supports annotating and cropping images directly in the markdown editor. It can be used to highlight areas, add labels, crop screenshots, and redact sensitive information without leaving the report.</p><p>The editor can be opened from the markdown preview: click an image to open the image dialog, then select <strong>Edit Image</strong>.</p><p><img src="/images/image-editor.png" alt="Image editor" width="1915" height="985"></p><p>The image editor supports the following annotations and tools:</p><ul><li><strong>Select:</strong> Move, resize, or rotate objects.</li><li><strong>Rectangle (outline)</strong> / <strong>Rectangle (filled):</strong> Draw rectangles.</li><li><strong>Ellipse:</strong> Draw ellipses.</li><li><strong>Line:</strong> Draw straight lines.</li><li><strong>Text:</strong> Place editable text labels.</li><li><strong>Numbered marker:</strong> Place markers with numbers; drag the tip to point at regions.</li><li><strong>Crop:</strong> Define a region; switch to another tool to apply.</li><li><strong>Color:</strong> Set stroke and fill for new and selected shapes.</li><li><strong>Stroke width:</strong> Set line thickness and text size.</li></ul><p><strong>Save</strong> updates the image and the markdown reference. If the image was edited before, <strong>Revert</strong> restores the original. Color and stroke width are remembered for the next session.</p><p>The original image is kept internally to support Revert. It is not included in reports and is never exported; only the annotated/redacted image is included.</p><h2 id="redacting-images" tabindex="-1">Redacting images <a class="header-anchor" href="#redacting-images" aria-label="Permalink to “Redacting images”">​</a></h2><p>Redaction is the removal or masking of sensitive information before an image is shared (e.g. passwords, API tokens, personal identifying information, etc.).</p><p>SysReptor offers multiple methods for redaction:</p><ul><li><strong>Pixelate</strong>: Suitable for hiding details while keeping the screenshot visually consistent.</li><li><strong>Filled rectangle</strong>: Suitable for a clear, unambiguous mask, especially for highly sensitive text such as secrets, credentials, or tokens.</li><li><strong>Crop</strong>: Suitable when the sensitive area can be removed entirely without losing important context.</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The pixelated region is generated without sampling any source pixels from inside the redacted area. Instead, synthetic pixels are derived from image content outside the selection (around redaction borders). As a result, the exported image contains no embedded data from the redacted area, and the original content cannot be recovered from the saved file.</p></div><p><img src="/images/image-editor-pixelate.gif" alt="Pixelate image" width="1534" height="1096"></p>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};